package com.primehr.migration;
import org.flywaydb.core.*;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV55ToV56UpgradeTest {@Test void populatedEvidenceSurvivesOperationsMigration()throws Exception{String db="primehr_v56_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String> placeholders=Map.of("primehrSchema","PUBLIC");Flyway initial=flyway(url,placeholders,"55");initial.migrate();try{Flyway upgraded=flyway(url,placeholders,"56");upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("56");try(var c=DriverManager.getConnection(url,"sa","");var rs=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.primehr_reconciliation_run")){rs.next();assertThat(rs.getLong(1)).isZero();}try(var c=DriverManager.getConnection(url,"sa","");var rs=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.evidence_readiness_snapshot")){rs.next();assertThat(rs.getLong(1)).isZero();}}finally{initial.clean();}}private Flyway flyway(String url,Map<String,String> p,String target){return Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion(target)).cleanDisabled(false).load();}}
